from nouns_theory import T,S

def build_tasks(c):
 def choice(prompt,opts,rule,context=None,passage=None,category=None):
  q=dict(id='nouns-practice-v1-q'+str(len(c['questions'])+1).zfill(2),type='choice',skill=category or rule,prompt=prompt,answerId='o0',options=[dict(id='o'+str(i),text=S(text) if isinstance(text,str) else text,feedback=why) for i,(text,why) in enumerate(opts)],ruleRefs=[rule])
  if context:q['context']=context
  if passage:q['passage']=passage
  c['questions'].append(q)
 def input(prompt,answer,why,rule,tokens=None,accepted=None):
  q=dict(id='nouns-practice-v1-q'+str(len(c['questions'])+1).zfill(2),type='arrange' if tokens else 'cloze',skill=rule,prompt=prompt,answer=answer,good=why,bad=why,ruleRefs=[rule])
  if tokens:q['tokens']=tokens
  if accepted:q['accepted']=accepted
  c['questions'].append(q)
